        const links = [{"text":"Documentation","url":"https://testsmith-io.github.io/practice-software-testing/#/","rawHref":"https://testsmith-io.github.io/practice-software-testing/#/","category":"navigation","linkType":"external","containerLabel":"","expectedStatus":null,"isVisible":true,"target":"_blank","targetBehavior":"new-tab","titleAttribute":"","downloadName":"","requiresAuth":false,"isSecure":true},{"text":"Barn Images","url":"https://unsplash.com/@barnimages","rawHref":"https://unsplash.com/@barnimages","category":"navigation","linkType":"external","containerLabel":"This is a DEMO application, used for software testing training purpose. | Banner photo by Barn Images on Unsplash.","expectedStatus":null,"isVisible":true,"target":"_blank","targetBehavior":"new-tab","titleAttribute":"","downloadName":"","requiresAuth":false,"isSecure":true},{"text":"Unsplash","url":"https://unsplash.com/photos/t5YUoHW6zRo","rawHref":"https://unsplash.com/photos/t5YUoHW6zRo","category":"navigation","linkType":"external","containerLabel":"This is a DEMO application, used for software testing training purpose. | Banner photo by Barn Images on Unsplash.","expectedStatus":null,"isVisible":true,"target":"_blank","targetBehavior":"new-tab","titleAttribute":"","downloadName":"","requiresAuth":false,"isSecure":true}];
        // TFP-142: each distinct URL is requested once, for up to 5 s, and
        // the check stops after 20 s. Requesting every link in turn at 15 s
