      const referrer = (headers['referrer-policy'] ?? ((await metaReferrer.count()) > 0 ? await metaReferrer.first().getAttribute('content') : null) ?? '').toLowerCase();
      if (!referrer) found.push('no referrer policy on /#/chainsaws (no Referrer-Policy header or meta referrer)');
      else if (/unsafe-url|no-referrer-when-downgrade/.test(referrer)) found.push('the referrer policy on /#/chainsaws (' + referrer + ') sends full URLs to other sites');
